"""Cash, pricing and turnover helpers."""
import tomllib
from decimal import Decimal
from pathlib import Path

from vendor.rounding import round_cents


def load_data():
    with open(Path(__file__).parent / "data.toml", "rb") as f:
        return tomllib.load(f)


def list_price(unit_cost, markup, mode):
    return round_cents(Decimal(unit_cost) * (1 + Decimal(str(markup))), mode)


def scale_pct(cents, pct, mode):
    """cents * pct / 100, rounded to a whole cent."""
    return round_cents(Decimal(cents) * Decimal(str(pct)) / Decimal(100), mode)


class Money:
    def __init__(self, cash):
        self.cash = cash
        self.overdrawn = False
        self.held_log = {}      # day -> units held when that day was closed
        self.shipped_log = {}   # day -> units shipped

    def adjust(self, delta, log, emit=True):
        self.cash += delta
        if emit:
            self.check(log)

    def check(self, log):
        if self.cash < 0:
            if not self.overdrawn:
                self.overdrawn = True
                log.emit("OVERDRAWN")
        else:
            self.overdrawn = False

    def record_shipped(self, day, qty):
        self.shipped_log[day] = self.shipped_log.get(day, 0) + qty

    def turnover(self, start_day, end_day):
        shipped = sum(v for d, v in self.shipped_log.items()
                      if start_day <= d <= end_day)
        held = [v for d, v in self.held_log.items() if start_day <= d <= end_day]
        if not held:
            return None
        avg = sum(held) / len(held)
        if avg == 0:
            return None
        return shipped / avg

    def to_dict(self):
        return {
            "cash": self.cash,
            "overdrawn": self.overdrawn,
            "held_log": [[d, v] for d, v in sorted(self.held_log.items())],
            "shipped_log": [[d, v] for d, v in sorted(self.shipped_log.items())],
        }

    @classmethod
    def from_dict(cls, d):
        m = cls(d["cash"])
        if type(m.cash) is not int:
            raise ValueError("bad cash")
        m.overdrawn = bool(d["overdrawn"])
        m.held_log = {int(a): int(b) for a, b in d["held_log"]}
        m.shipped_log = {int(a): int(b) for a, b in d["shipped_log"]}
        return m
