"""Supplier reliability and orders."""

START = 3
LOW, HIGH = 0, 5
SUSPEND_AT = 1


class Suppliers:
    def __init__(self):
        self.rel = {}
        self.orders = {}
        self.next_id = 1

    def suspended(self, supplier):
        return supplier in self.rel and self.rel[supplier] <= SUSPEND_AT

    def ensure(self, supplier):
        self.rel.setdefault(supplier, START)

    def bump(self, supplier, delta, log):
        old = self.rel[supplier]
        new = max(LOW, min(HIGH, old + delta))
        self.rel[supplier] = new
        if old > SUSPEND_AT and new <= SUSPEND_AT:
            log.emit("SUPPLIER_SUSPENDED", supplier)

    def reinstate(self, supplier):
        self.rel[supplier] = 2

    def add_order(self, supplier, sku, qty, due_day, wh):
        oid = self.next_id
        self.next_id += 1
        self.orders[oid] = {"supplier": supplier, "sku": sku, "qty": qty,
                            "due_day": due_day, "wh": wh, "delivered": False}
        return oid

    def to_dict(self):
        return {
            "rel": dict(self.rel),
            "next_id": self.next_id,
            "orders": [dict(o, id=i) for i, o in sorted(self.orders.items())],
        }

    @classmethod
    def from_dict(cls, d):
        s = cls()
        s.rel = {str(k): int(v) for k, v in d["rel"].items()}
        s.next_id = int(d["next_id"])
        for o in d["orders"]:
            s.orders[int(o["id"])] = {
                "supplier": str(o["supplier"]), "sku": str(o["sku"]),
                "qty": int(o["qty"]), "due_day": int(o["due_day"]),
                "wh": str(o["wh"]), "delivered": bool(o["delivered"]),
            }
        return s
